if (!/<a\s[^>]*href=/i.test(code) && !/<a\s+href=/i.test(code)) {
  throw new Error("No anchor (<a>) element with an href found.");
}

const m = code.match(/href\s*=\s*["']([^"']*)["']/i);
if (!m || m[1] !== "https://example.com") {
  throw new Error("The href must be exactly: https://example.com");
}

const m = code.match(/<a\s[^>]*>([\s\S]*?)<\/a\s*>/i);
if (!m || m[1].trim() !== "Learn more") {
  throw new Error("The anchor text must be exactly: Learn more");
}
